const DURATIONS=[[30,'Essai · 30 s','essai rapide, le moins cher, non monétisable'],[60,'Courte · 1 min','le minimum pour la monétisation TikTok : le moins de planches et de clips à payer'],[120,'Moyenne · 2 min','plus de temps de visionnage'],[180,'Longue · 3 min','épisode long'],[240,'Très longue · 4 min','le plus cher']];
