const MODES=[['ideas','Pas d’idée','10 histoires proposées'],['idea','J’ai une idée','ton idée devient une fiche'],['link','Refaire une virale','d’après une vidéo TikTok'],['research','Décide tout à ma place','recherche, histoire, vidéo']];
