 const key={views:x=>x.views||0,fast:x=>x.f.per_hour||0,growth:x=>x.f.growth||0,engagement:x=>x.f.engagement||0,habit:x=>median[x.account]?(x.views||0)/median[x.account]:0,recent:x=>-(x.age??9999)}[filonSort]||(x=>x.views||0);items.sort((p,r)=>key(r)-key(p));
 const viralCount=all.filter(x=>x.viral).length,todayCount=all.filter(x=>x.viral&&(x.age??99)<=1).length;
