// --- Créer une vidéo: full page, four steps like the Atelier ----------------------------------
openCreate=url=>{if(url){draft.mode='link';draft.source=url;}page='create';selected=null;render();window.scrollTo(0,0);};
const chip=(group,value,label,sub,on)=>`<button type="button" class="choice ${on?'on':''}" data-choice="${group}" data-value="${esc(value)}"><b>${label}</b>${sub?`<small>${sub}</small>`:''}</button>`;
// Durée garantie (same rule as montage.scenes_for): enough plans to pass the target, fades included.
function planCount(duration,seconds){const goal=duration+(duration>=60?1:0),fade={cut:0,fade_short:.25,fade_long:.6}[state.montage?.transition]||0;let n=Math.max(3,Math.ceil(goal/seconds));while(n<40&&n*seconds-fade*(n-1)<goal)n++;return Math.min(n,40);}
function createPage(){const lang=draft.language||state.settings.language||'Français (fr-FR)';const seconds={flow:8,grok:6,arena:8}[draft.engine];const scenes=planCount(draft.duration,seconds);
 const cost=draft.engine==='flow'?scenes*12:null;const step=(n,title,body)=>`<section class="panel create-step"><h3><span>${n}</span>${title}</h3>${body}</section>`;
 const action={ideas:'Propose-moi dix histoires',idea:'Écrire la fiche',link:'Recréer cette vidéo',research:'Lancer la recherche et l’histoire'}[draft.mode];
 return `<div class="intro"><div><h1>Créer</h1><p>Une histoire en quatre temps. Rien n’est payé avant que tu aies validé l’histoire.</p></div></div>
<ol class="wizard"><li class="done"><b>Qui écrit</b><small>Claude ou ChatGPT</small></li><li class="current"><b>Quoi</b><small>une idée, une virale</small></li><li><b>Décider</b><small>la fiche, tu valides</small></li><li><b>Fabriquer</b><small>planches, clips, montage</small></li></ol>
<form id="createForm" class="create-page">
${step(1,'Écrite par',`<div class="choices two">${chip('provider','chatgpt','ChatGPT','chatgpt.com, ton compte',draft.provider==='chatgpt')}${chip('provider','claude','Claude','claude.ai, ton compte',draft.provider==='claude')}</div>${draft.provider==='claude'?claudeOptions():'<p class="hint">Les images sont toujours dessinées par ChatGPT, dans la fenêtre FruchtDrama.</p>'}`)}
${step(2,'Option',`<div class="choices four">${MODES.map(([k,l,s])=>chip('mode',k,l,s,draft.mode===k)).join('')}</div>
<div class="create-row"><div><h4>Niche</h4><div class="chips">${NICHES.map(n=>chip('niche',n,n,'',draft.niche===n)).join('')}</div></div></div>
<div class="create-row"><div><h4>Durée</h4><div class="chips">${DURATIONS.map(([v,l])=>chip('duration',v,l,'',draft.duration===v)).join('')}</div><p class="hint">${esc(DURATIONS.find(d=>d[0]===draft.duration)[2])} · ${scenes} plans de ${seconds} s${cost?` · ≈ ${cost} crédits Flow (Omni)`:''}.</p></div>
<div><h4>Moteur vidéo</h4><div class="chips">${ENGINES.map(([k,l,s])=>chip('engine',k,l,s,draft.engine===k)).join('')}</div></div></div>
<div class="create-row"><div><h4>Langue</h4><div class="chips">${LANGS.map(([v,l])=>chip('language',v,l,'',lang===v)).join('')}</div><p class="hint">Les répliques, le titre, les voix et les sous-titres dans cette langue.</p></div><div><h4>Format</h4><div class="chips">${FORMATS.map(([k,l,s])=>chip('format',k,l,s,draft.format===k)).join('')}</div></div></div>
<div class="create-row"><div><h4>Qualité</h4><div class="chips">${QUALITIES.map(([k,l,s])=>chip('quality',k,l,s,draft.quality===k)).join('')}</div></div></div>`)}
${step(3,{ideas:'Ta demande',idea:'Ton idée',link:'La vidéo à refaire',research:'La recherche'}[draft.mode],
 draft.mode==='ideas'?`<p class="hint">L’IA te propose dix histoires taillées pour la niche, d’après le Filon ; tu en choisis une.</p><label>Instructions en plus (facultatif)<textarea name="brief" rows="2" placeholder="Ex. une mère pêche, un retournement plus violent à la fin…"></textarea></label>`
 :draft.mode==='idea'?`<label>L’histoire, en quelques phrases<textarea name="brief" rows="4" required minlength="15" placeholder="À dix ans, un petit citron découvre que…"></textarea></label>`
 :draft.mode==='link'?`<label>Lien TikTok<input name="source_url" type="url" required value="${esc(draft.source)}" placeholder="https://www.tiktok.com/@compte/video/123…"></label><p class="hint">Le studio récupère la vidéo, en tire ses moments clés et ce qui y est dit, et les montre à l’IA. La vidéo reste sur ton ordinateur. L’originalité est estimée avant publication.</p>
<label class="check"><input type="checkbox" name="recreate" ${draft.recreate?'checked':''}> Recréer à l’identique<span class="hint">Mêmes scènes dans le même ordre, mêmes rôles, même fin ; chaque réplique est reformulée, les prénoms changent. Sans la case : histoire originale inspirée de la vidéo. Attention : plus la vidéo ressemble à l’originale, plus TikTok risque de la juger non originale (moins de vues, pas de monétisation).</span></label>
<label>Captures en plus (facultatif)<input name="captures" type="file" accept="image/png,image/jpeg,image/webp" multiple><span class="hint">Jusqu’à 4 images : moments de la vidéo, ou ta photo pour un personnage. 8 Mo au plus chacune.${captureFiles.length?` <b>${captureFiles.length} capture(s) choisie(s).</b>`:''}</span></label>
<label>Instructions en plus (facultatif)<textarea name="brief" rows="2" placeholder="Ex. mets ma tête (2ᵉ capture) à la place du père ; la fin se passe à la plage…"></textarea></label>${filonRows().length?`<div class="mini-filon">${filonRows().slice(0,8).map(c=>`<button type="button" class="mini-card ${draft.source===c.url?'on':''}" data-pick-source="${esc(c.url)}"><img src="/api/thumb?url=${encodeURIComponent(c.url)}" alt="" onerror="this.classList.add('missing')"></button>`).join('')}</div>`:''}`
 :`<label>Recherche TikTok<input name="query" value="${esc(state.settings.query||'')}"></label><label>Idée pour orienter (facultatif)<textarea name="brief" rows="2"></textarea></label>`)}
${step(4,'Fabrication',`<label class="check"><input type="checkbox" name="auto" checked> Lancer la production automatiquement<span class="hint">Dès que la fiche passe les contrôles : planches (ChatGPT), clips, montage. Décoché : tu valides la fiche toi-même avant tout paiement.</span></label>
<div class="create-row"><div><h4>Personnages</h4><div class="chips">${chip('characters','simple','Simple','feuille de face','simple'===draft.characters)}${chip('characters','detailed','Détaillé','trois quarts, gros plan, détails','detailed'===draft.characters)}</div></div>
<div><h4>Sous-titres</h4><div class="chips">${chip('subtitles','without','Sans','seul le hook reste écrit',draft.subtitles==='without')}${chip('subtitles','with','Avec',state.montage?.karaoke===false?'simples':'karaoké',draft.subtitles==='with')}</div><p class="hint">Montage : ${esc(state.montage_summary||'')} · à régler dans Mes comptes.</p></div></div>
<label class="check"><input type="checkbox" name="dry_run"> Essai à blanc des clips<span class="hint">Tout est préparé, rien n’est envoyé ni payé.</span></label>
<details class="flow-settings" ${draft.engine==='flow'?'':'hidden'}><summary>Réglages Flow</summary><div class="form-grid"><label>Modèle<select name="flow_model"><option value="gemini_omni_flash">Gemini Omni Flash · 12 crédits</option><option value="veo_3_1_lite">Veo 3.1 Lite · 10 crédits</option><option value="veo_3_1_fast">Veo 3.1 Fast · 20 crédits</option><option value="veo_3_1_quality">Veo 3.1 Quality · 100 crédits</option></select></label><label>Résolution des clips<select name="flow_resolution"><option value="1080p">1080p · meilleure qualité (si ton compte la propose)</option><option value="720p">720p</option></select></label><label>Compte Flow<select name="flow_profile" id="createProfile">${profileOptions(state.profiles[0]?.id)}</select></label></div></details>`)}
<div class="create-submit"><button class="primary big" type="submit">${ico('create')} ${action}</button></div></form>${recoveredList()}`}
// Atelier « Vidéos déjà récupérées »: every TikTok video already taken for a recreation, with its episode.
function recoveredList(){const by=new Map();for(const j of state.jobs)if(j.selected?.url&&!j.variant&&!by.has(j.selected.url))by.set(j.selected.url,j);if(!by.size)return '';
 return `<details class="recovered"><summary>Vidéos déjà récupérées (${by.size})</summary><div class="recovered-list">${[...by.entries()].map(([url,j])=>`<div class="recovered-row"><img src="/api/thumb?url=${encodeURIComponent(url)}" alt="" loading="lazy" onerror="this.style.visibility='hidden'"><div><b>${esc(displayTitle(j))}</b><small>@${esc((url.match(/@([^/]+)/)||[])[1]||'')} · ${esc(statusLabels[j.status]||j.status)}</small></div><button class="secondary" data-open-episode="${j.id}">Ouvrir l’épisode</button></div>`).join('')}</div></details>`}
// An episode still untitled shows where it comes from instead of « Nouvel épisode ».
const displayTitle=j=>j.title&&j.title!=='Nouvel épisode'?j.title:j.selected?.url?'Recréation de @'+((j.selected.url.match(/@([^/]+)/)||[])[1]||'TikTok'):j.title||'Nouvel épisode';
function syncCreate(){}
// Captures and the "à l'identique" box survive the re-render of a chip click (a file input cannot be refilled).
var captureFiles=[];
document.addEventListener('change',e=>{if(page!=='create')return;if(e.target.name==='captures'){captureFiles=[...e.target.files];if(captureFiles.length>4)toast('4 captures au plus : seules les 4 premières seront envoyées.');captureFiles=captureFiles.slice(0,4);}if(e.target.name==='recreate')draft.recreate=e.target.checked;
 if(e.target.dataset?.claudeSetting!==undefined){const k=e.target.name,v=e.target.value;draft[k]=v;state.settings[k]=v;api('/api/settings',{[k]:v}).catch(err=>toast(err.message));}});
document.addEventListener('click',e=>{const c=e.target.closest?.('[data-choice]');if(c&&page==='create'){const v=c.dataset.value;draft[c.dataset.choice]=c.dataset.choice==='duration'?Number(v):v;const keep=[...document.querySelectorAll('#createForm textarea,#createForm input[name=source_url]')].map(x=>[x.name,x.value]);render();keep.forEach(([n,v])=>{const x=document.querySelector(`#createForm [name=${n}]`);if(x&&v)x.value=v;});return}
 const s=e.target.closest?.('[data-pick-source]');if(s){draft.source=s.dataset.pickSource;render();}},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='createForm')return;e.preventDefault();e.stopImmediatePropagation();const f=new FormData(e.target);const auto=f.get('auto')==='on';
 const lang=draft.language||state.settings.language||'Français (fr-FR)';
 const body={mode:draft.mode==='research'?'research':draft.mode,brief:String(f.get('brief')||'').trim(),source_url:draft.mode==='link'?String(f.get('source_url')||'').trim():'',flow_profile:f.get('flow_profile')||state.profiles[0]?.id,
  config:{provider:draft.provider,...(draft.provider==='claude'?{claude_model:claudeChoice('claude_model'),claude_effort:claudeChoice('claude_effort')}:{}),duration:draft.duration,scene_count:4,niche:draft.niche,language:lang,video_engine:draft.engine,flow_model:f.get('flow_model')||'gemini_omni_flash',flow_resolution:f.get('flow_resolution')||'720p',...(draft.mode==='link'?{recreate:f.get('recreate')==='on'?'identical':'inspired'}:{}),auto_sheet:auto,review_script:!auto,dry_run:f.get('dry_run')==='on',quality:draft.quality,format:draft.format,characters:draft.characters,subtitles:draft.subtitles==='with',...(draft.mode==='research'&&f.get('query')?{query:f.get('query')}:{})}};
 if(auto&&!body.config.dry_run&&draft.mode!=='ideas'){const seconds={flow:8,grok:6,arena:8}[draft.engine];if(!window.confirm('Production automatique : l’IA écrit l’histoire, puis le studio fait tout sans te demander : planches, clips, montage et miniature.\n\nÇa consomme '+costText(planCount(draft.duration,seconds))+'.\n\nOn y va ?'))return;}
 if(draft.mode==='link'){const files=captureFiles;if(files.length>4){toast('4 captures au plus.');return;}if(files.some(x=>x.size>8*1024*1024)){toast('Capture trop lourde : 8 Mo au plus par image.');return;}body.captures=await Promise.all(files.map(x=>new Promise((ok,ko)=>{const r=new FileReader();r.onload=()=>ok({name:x.name,data:r.result});r.onerror=()=>ko(Error('Capture illisible'));r.readAsDataURL(x);})));}
 if(draft.mode==='research'&&!body.brief)body.brief='Choisis le sujet après la recherche des références. Invente une histoire originale adaptée à la référence retenue, sans en copier les dialogues ou les plans.';
 try{const st=await api('/api/job',body);selected=st.jobs[0].id;page='studio';draft.source='';captureFiles=[];draft.recreate=false;await refresh(true);location.hash='job='+selected;toast({ideas:'Dix histoires demandées',idea:'Fiche de décision en cours',link:'Recréation lancée',research:'Recherche lancée'}[draft.mode]);}catch(err){toast(err.message)}},true);

// --- Studio: large illustrated cards ---------------------------------------------------------
let studioFilter='all';
const cover=j=>j.cover||(j.scenes||[]).map(x=>x.image).filter(Boolean).map(x=>assetURL(j,x))[0]||(j.character_sheet_file?assetURL(j,j.character_sheet_file):(j.characters||[]).map(c=>c.file).filter(Boolean).map(x=>assetURL(j,x))[0]);
function segments(j){const n=(j.scenes||[]).length||j.config.scene_count||1,img=(j.scenes||[]).filter(s=>s.image).length,clip=(j.scenes||[]).filter(s=>s.clip).length,order=['ideas','sheet','research','script','characters','images','clips','quality','cover','edit','done'],at=order.indexOf(j.stage);
 return [['Fiche',at>3?1:at>=0?Math.min(1,(at+1)/5):0,at>3?'validée':at===3?'scénario en cours':at===1&&j.sheet?'à valider':'à écrire'],['Personnages',at>4?1:0,at>4?'prêts':'à faire'],['Planches',at>5?1:img/n,img+'/'+n],['Clips',at>7?1:clip/n,clip+'/'+n],['Montage',j.final?1:at>=9?0.5:0,j.final?'prêt':'à faire']];}
function nextAction(j){const t=state.tasks.find(t=>t.job===j.id&&['queued','claimed'].includes(t.status));if(j.status==='done')return 'Prête à télécharger';if(j.stage==='ideas'&&j.ideas?.length)return 'Choisis une des dix histoires';if(j.stage==='sheet'&&j.status==='waiting_review')return 'Valide la fiche de décision';if(t)return (t.status==='claimed'?'En cours : ':'En attente : ')+({ideas:'dix histoires',sheet:'fiche',script:'écriture des plans',characters:'feuille des personnages',cover:'miniature'}[t.slot]||t.slot.replace('image:','planche ').replace('clip:','clip '));return statusLabels[j.status]||j.status;}
function card(j){const c=cover(j),seg=segments(j),ready=j.status==='done';return `<button class="studio-card" data-job="${j.id}">${c?`<img src="${c}" alt="">`:`<span class="studio-ph">${ico('film')}</span>`}<span class="studio-badge ${ready?'ready':''}">${ready?'Prête':'À finir'}</span><span class="studio-body"><b>${esc(j.title)}</b><small>${esc(j.config.duration?Math.round(j.config.duration/60*10)/10+' min':((j.scenes||[]).length||j.config.scene_count)*(j.config.clip_seconds||8)+' s')} · ${esc((j.config.language||'').split(' ')[0])} · ${esc(({flow:'Flow',grok:'Grok',arena:'Arena'})[j.config.video_engine||'flow'])}</small><span class="seg">${seg.map(([l,v])=>`<i title="${l}" style="--v:${Math.round(v*100)}%"></i>`).join('')}</span><small class="next">${esc(nextAction(j))}</small></span></button>`}
function studio(){if(selected&&state.jobs.some(j=>j.id===selected))return detail();
 const g=state.jobs.reduce((a,j)=>(a[stageGroup(j)]=(a[stageGroup(j)]||0)+1,a),{});const jobs=state.jobs.filter(j=>studioFilter==='all'||(studioFilter==='ready'?j.status==='done':j.status!=='done'));
 return `<div class="intro"><div><h1>Studio</h1><p>Tes épisodes, de l’idée à la vidéo finale.</p></div><button class="primary" data-action="new">${ico('plus')} Nouvelle histoire</button></div>${nightPanel()}
<div class="studio-counters">${[['write','à écrire'],['draw','à dessiner'],['shoot','à tourner'],['ready','prêtes']].map(([k,l])=>`<div><strong>${g[k]||0}</strong><small>${l}</small></div>`).join('')}<div class="filters">${[['all','Toutes'],['open','En cours'],['ready','Prêtes']].map(([k,l])=>`<button class="${studioFilter===k?'primary':'secondary'}" data-studio-filter="${k}">${l}</button>`).join('')}</div></div>
<div class="studio-grid"><button class="studio-card new" data-action="new"><span class="studio-ph">${ico('plus')}</span><span class="studio-body"><b>Nouvelle histoire</b><small>d’un lien ou d’une idée</small></span></button>${jobs.map(card).join('')}</div>`}
document.addEventListener('click',e=>{const f=e.target.closest?.('[data-studio-filter]');if(f){studioFilter=f.dataset.studioFilter;render();}const b=e.target.closest?.('[data-back-studio]');if(b){selected=null;history.replaceState(null,'',location.pathname);render();}},true);

// --- Episode page: tracker, ten stories, decision sheet, scenes and clips side by side --------
function ideasPanel(j){if(j.stage!=='ideas')return '';if(!j.ideas?.length)return `<div class="notice dry"><b>${({chatgpt:'ChatGPT',claude:'Claude'})[j.config.provider]} cherche dix histoires…</b><p class="hint">En général 1 à 4 minutes. Rien n’est payé à cette étape.</p></div>`;
 return `<section class="panel ideas"><div class="section-title"><h2>Dix histoires</h2><button class="secondary" data-command="more_ideas">Dix autres</button></div><p class="hint">Clique celle que tu veux : elle devient ta demande.</p><div class="idea-grid">${j.ideas.map((x,i)=>`<button class="idea" data-idea="${i}"><b>${esc(x.title)}</b><span>${esc(x.pitch)}</span><small>${esc(x.why)}</small></button>`).join('')}</div></section>`}
function sheetPanel(j){if(j.stage!=='sheet')return '';const s=j.sheet;if(!s)return `<div class="notice dry"><b>Fiche de décision en cours…</b><p class="hint">L’IA écrit le moteur, l’obstacle, le twist, trois titres, trois premières répliques et trois appels de fin.</p></div>`;
 const field=(k,l,rows=3)=>`<label class="sheet-field">${l}<textarea data-sheet="${k}" rows="${rows}">${esc(s[k])}</textarea></label>`;
 return `<section class="panel sheet" id="sheetPanel"><div class="section-title"><h2>La fiche de décision</h2><span class="tag">étape 1 sur 2</span></div><p class="hint">Valide l’histoire avant que l’IA écrive les plans. Rien n’est dessiné ni filmé avant.</p>${j.sheet_precheck&&j.sheet_precheck.level!=='low'?`<div class="notice ${j.sheet_precheck.level==='high'?'human':'dry'}"><b>Risque de contenu non original : ${j.sheet_precheck.similarity} % de mots communs avec la vidéo d’origine</b>${j.sheet_precheck.advice.map(a=>`<p class="hint">${esc(a)}</p>`).join('')}<button class="primary" data-command="distance">Réécrire la fiche pour s’éloigner de l’original</button></div>`:''}
${field('logline','L’histoire en une phrase',2)}<div class="sheet-grid">${field('engine','Moteur')}${field('obstacle','Obstacle')}${field('twist','Twist')}</div><div class="sheet-grid two">${field('image','Ce qu’on voit en une image')}${field('question','La question du spectateur')}</div>
<h4>Le titre</h4><div class="chips">${s.titles.map((t,i)=>`<label class="choice radio"><input type="radio" name="sheetTitle" value="${i}" ${i===0?'checked':''}><b>${esc(t)}</b></label>`).join('')}</div>
<h4>La première réplique</h4><div class="chips column">${s.hooks.map((t,i)=>`<label class="choice radio"><input type="radio" name="sheetHook" value="${i}" ${i===0?'checked':''}><b>« ${esc(t)} »</b></label>`).join('')}</div>
${(s.end_calls||[]).length?`<h4>L’appel de fin</h4><p class="hint">Dit à la fin par un personnage : il fait commenter et s’abonner. Choisis-en un, modifie le texte si tu veux.</p><div class="chips column calls">${s.end_calls.map((t,i)=>`<label class="choice radio call"><input type="radio" name="sheetCall" value="${i}" ${i===0?'checked':''}><textarea data-call="${i}" rows="2" aria-label="Appel de fin ${i+1}">${esc(t)}</textarea></label>`).join('')}</div>`:field('end_call','L’appel de fin (abonnement et commentaires)',2)}<h4>Le casting</h4><div class="cast">${s.cast.map((c,i)=>`<label>${esc(c.role)}<input data-cast="${i}" value="${esc(c.name)}"><small>${esc(c.appearance)}</small></label>`).join('')}</div>
<label>Tu veux changer quelque chose ?<textarea id="sheetNote" rows="2" placeholder="Ex. rends le père plus ambigu, ajoute la mère à la fin…"></textarea></label>
<div class="actions"><button class="primary" data-sheet-approve="1">${ico('check')} Valider et écrire l’épisode</button><button class="secondary" data-sheet-revise="1">Revoir la fiche avec mes remarques</button></div></section>`}
const sheetEdits=()=>{const out={cast:[]};document.querySelectorAll('[data-sheet]').forEach(x=>out[x.dataset.sheet]=x.value);const calls=[...document.querySelectorAll('[data-call]')];if(calls.length)out.end_calls=calls.map(x=>x.value);document.querySelectorAll('[data-cast]').forEach(x=>out.cast[Number(x.dataset.cast)]={name:x.value});return out};
document.addEventListener('input',e=>{if(e.target.closest?.('#sheetPanel'))reviewDirty=true;});
// Editing a call also picks it (a click inside the text does not reach the hidden radio).
document.addEventListener('focusin',e=>{const c=e.target.closest?.('[data-call]');if(c){const r=document.querySelector(`[name=sheetCall][value="${c.dataset.call}"]`);if(r)r.checked=true;}});
document.addEventListener('click',async e=>{const el=e.target.closest?.('[data-idea],[data-sheet-approve],[data-sheet-revise]');if(!el)return;e.stopImmediatePropagation();try{
 if(el.dataset.idea){await api('/api/job/'+selected,{action:'pick_idea',index:Number(el.dataset.idea)});toast('Histoire choisie : fiche de décision en cours');}
 if(el.dataset.sheetApprove){await api('/api/job/'+selected,{action:'approve_sheet',sheet:sheetEdits(),title:Number(document.querySelector('[name=sheetTitle]:checked')?.value||0),hook:Number(document.querySelector('[name=sheetHook]:checked')?.value||0),call:Number(document.querySelector('[name=sheetCall]:checked')?.value||0)});toast('Fiche validée : écriture des plans');}
 if(el.dataset.sheetRevise){await api('/api/job/'+selected,{action:'revise_sheet',sheet:sheetEdits(),note:$('#sheetNote').value});toast('Fiche renvoyée avec tes remarques');}
 reviewDirty=false;await refresh(true);}catch(err){toast(err.message)}},true);
function trackAction(j,i,v){const idle=j.status!=='running';const a={1:(j.character_sheet_file||j.characters?.some(c=>c.file))?`<button class="link-btn" data-redo="${usesSheet(j)?'characters':'character:'+j.characters[0].id}">Refaire…</button>`:'',2:v<1&&idle&&j.stage==='images'?'<button class="link-btn" data-command="resume">Générer</button>':'',3:v<1&&idle&&j.stage==='clips'?'<button class="link-btn" data-command="resume">Générer</button>':''}[i];return a?`<span class="track-act">${a}</span>`:''}
// Atelier-like thumbnail: pick the board the cover is drawn from.
function coverPanel(j){const boards=j.scenes.map((s,i)=>[s,i]).filter(([s])=>s.image);if(!boards.length)return '';const base=Number.isInteger(j.cover_base)?j.cover_base:boards[0][1];
 return `<section class="panel cover-panel"><div class="cover-now">${j.cover?`<img src="${j.cover}" alt="Miniature">`:'<span>Miniature</span>'}</div><div><h3>Miniature</h3><div class="cover-picks">${boards.slice(0,8).map(([s,i])=>`<button class="${i===base?'on':''}" data-cover-base="${i}" title="Scène ${i+1}"><img src="${assetURL(j,s.image)}" alt=""></button>`).join('')}</div>${j.cover_file?'<button class="primary" data-redo="cover">Refaire la miniature…</button>':'<button class="primary" data-cover-make="1">Faire la miniature</button>'}${j.cover?'':'<p class="hint">Faite après les clips, depuis la scène choisie.</p>'}</div></section>`}
function textModal(j){const names=Object.fromEntries(j.characters.map(c=>[c.id,c.name]));return `<div class="text-modal"><h2>${esc(j.title)}</h2>${j.scenes.map((s,i)=>`<div class="text-scene"><b>${i+1}. ${esc(shortTitle(s))}</b>${(s.dialogue||[]).map(l=>`<p><b>${esc((names[l.speaker]||l.speaker).toUpperCase())}</b> « ${esc(l.text)} »</p>`).join('')}</div>`).join('')}</div><button class="secondary" data-scene-close="1">Fermer</button>`}
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-cover-base],[data-cover-make],[data-show-text]');if(!b)return;e.stopImmediatePropagation();const j=state.jobs.find(x=>x.id===selected);if(!j)return;try{
 if(b.dataset.showText){let box=$('#sceneBox');if(!box){box=document.createElement('dialog');box.id='sceneBox';box.addEventListener('click',ev=>{if(ev.target===box)box.close()});document.body.append(box);}box.innerHTML=textModal(j);box.showModal();return}
 if(b.dataset.coverBase){await api('/api/job/'+j.id,{action:'cover_base',index:Number(b.dataset.coverBase)});await refresh(true);return}
 if(b.dataset.coverMake){const base=Number.isInteger(j.cover_base)?j.cover_base:j.scenes.findIndex(s=>s.image);if(j.cover_file&&!window.confirm('Refaire la miniature depuis la scène '+(base+1)+' ?'))return;await api('/api/job/'+j.id,{action:'cover_base',index:base,make:true});await refresh(true);toast(j.cover_file?'Nouvelle miniature demandée':'Miniature prévue depuis cette scène');}}catch(err){toast(err.message)}},true);
// Estimated originality before publishing (TikTok does not publish its method).
function originalityPanel(j){const o=j.originality;if(!j.final&&!o)return '';if(!o)return `<section class="panel orig"><h3>Originalité</h3><p class="hint">Pas encore contrôlée.</p><button class="secondary" data-command="originality">Contrôler l’originalité</button></section>`;
 const tone={publish:'ok',fix:'warn',hold:'bad'}[o.verdict],label={publish:'Publication conseillée',fix:'Corrigez avant de publier',hold:'Publication déconseillée'}[o.verdict];
 return `<section class="panel orig ${tone}"><div class="orig-head"><div class="orig-score"><strong>${o.score} %</strong><small>originalité estimée</small></div><div><h3>${label}</h3><p class="hint">${esc(o.note)}</p></div><button class="secondary" data-command="originality">Recalculer</button></div>
<div class="orig-factors">${o.factors.map(f=>`<div class="${f.risk>=20?'bad':f.risk>0?'warn':'ok'}"><b>${esc(f.label)}</b><span>${f.risk?'−'+f.risk:'OK'}</span><small>${esc(f.detail)}</small></div>`).join('')}</div>
${o.advice.length?`<h4>À changer pour s’éloigner de l’original</h4><ul class="orig-advice">${o.advice.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><button class="primary" data-command="distance">Réécrire titre, accroche et description pour s’éloigner</button>`:''}</section>`}
// Atelier-like versions: horizontal 16:9 and other languages, made from this episode.
function variantLinks(j){const of=state.jobs.filter(x=>x.variant?.of===j.id);const can=j.script&&j.scenes?.some(s=>s.image);
 const others=LANGS.filter(([v])=>v!==j.config.language&&!of.some(x=>x.variant.kind==='language'&&x.config.language===v));
 return `<div class="variants">${of.map(x=>`<button class="chip-link" data-job="${x.id}">${x.variant.kind==='horizontal'?'16:9':esc(x.config.language.split(' ')[0])} · ${esc(statusLabels[x.status]||x.status)}</button>`).join('')}
${can&&j.config.format!=='horizontal'&&!of.some(x=>x.variant.kind==='horizontal')?'<button class="chip-link add" data-variant="horizontal">+ Version horizontale 16:9</button>':''}
${can&&others.length?`<details class="lang-menu"><summary class="chip-link add">Langues</summary>${others.map(([v,l])=>`<button class="secondary" data-variant="language" data-language="${v}">${l}</button>`).join('')}</details>`:''}</div>`}
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-variant]');if(!b)return;e.stopImmediatePropagation();const j=state.jobs.find(x=>x.id===selected);if(!j)return;
 const what=b.dataset.variant==='horizontal'?'la version horizontale 16:9 (planches redessinées, clips et montage refaits : crédits ChatGPT et '+(j.config.video_engine==='flow'||!j.config.video_engine?'Flow':j.config.video_engine)+')':'la version '+b.dataset.language.split(' ')[0]+' (mêmes planches ; répliques, voix et clips refaits : crédits vidéo)';
 if(!window.confirm('Créer '+what+' ?'))return;try{const r=await api('/api/job/'+j.id,{action:'variant',kind:b.dataset.variant,language:b.dataset.language});selected=r.created;await refresh(true);toast('Nouvelle version créée');}catch(err){toast(err.message)}},true);
function progress(j){const seg=segments(j);return Math.round(seg.reduce((a,x)=>a+x[1],0)/seg.length*100);}
function tracker(j){const seg=segments(j),t=state.tasks.find(t=>t.job===j.id&&['queued','claimed'].includes(t.status)),pc=progress(j);
 return `<div class="tracker">${seg.map(([l,v,txt],i)=>`<div class="track ${v>=1?'done':v>0||i===seg.findIndex(x=>x[1]<1)?'current':''}"><span class="track-label">${v>=1?`<i class="ok">${ico('check')}</i>`:`<i>${i+1}</i>`}${l}</span><strong>${esc(txt)}</strong>${trackAction(j,i,v)}</div>`).join('')}</div>
${j.status!=='done'?`<div class="run-bar"><div class="run-head"><b>${j.status==='running'?'Fabrication':esc(statusLabels[j.status]||j.status)}</b><span class="live-line" title="Dernière ligne du journal">${esc(liveLine(j))}</span>${j.status==='running'?`<time class="run-clock" data-job="${j.id}">${runClock(j)}</time>`:''}<em>${pc} %</em>${j.status==='paused'?'<button class="secondary" data-command="resume">Reprendre</button>':'<button class="secondary" data-command="pause">Pause</button>'}</div><div class="bar"><i style="width:${pc}%"></i></div></div>`:''}`}
const shortTitle=s=>s.title||String(s.meaning||'').split(/[.,;:!?]/)[0].split(/\s+/).slice(0,6).join(' ');
function sceneTile(j,s,i){const sec=j.config.clip_seconds||8;return `<button class="scene-tile" data-scene-open="${i}">${s.image?`<img src="${assetURL(j,s.image)}" alt="Planche ${i+1}">`:`<span class="tile-ph">${ico('image')}</span>`}<span class="tile-n">${i+1}</span><span class="tile-s">${sec} s</span><span class="tile-icons"><i class="${s.image?'on':''}" title="Planche">${ico('image')}</i><i class="${s.clip?'on':''}" title="Clip">${ico('film')}</i></span><b>${esc(shortTitle(s)||'Scène '+(i+1))}</b></button>`}
// « Remettre » (like the Atelier): earlier boards and clips of the scene, newest first.
function versions(j,slot,video){const list=(j.redo_history||[]).filter(h=>h.slot===slot&&h.file).slice().reverse();if(!list.length)return '';
 const when=at=>{const d=new Date(at);return (d.toDateString()===new Date().toDateString()?'aujourd’hui ':d.toLocaleDateString('fr-FR')+' ')+d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});};
 return `<details class="versions"><summary>↶ ${list.length} version(s) précédente(s)</summary>${list.map(h=>`<div class="version">${video?`<video src="${assetURL(j,h.file)}" preload="metadata" muted></video>`:`<img src="${assetURL(j,h.file)}" alt="">`}<small>${esc(when(h.at))}${h.note?' · '+esc(h.note):''}</small><button class="secondary" data-restore="${slot}" data-file="${esc(h.file)}">Remettre</button></div>`).join('')}</details>`;}
function sceneModal(j,i){const s=j.scenes[i],names=Object.fromEntries(j.characters.map(c=>[c.id,c.name]));
 return `<div class="scene-modal"><div class="scene-pair"><div class="asset">${s.image?`<img src="${assetURL(j,s.image)}" alt="Planche ${i+1}">`:`<div class="asset-placeholder">${ico('image')}<small>planche à dessiner</small></div>`}<div class="mini-actions"><button class="secondary" data-upload="image:${i}" data-type="image">${s.image?'Remplacer':'Importer'}</button>${s.image?`<button class="secondary redo" data-redo="image:${i}" data-has-clip="${s.clip?1:0}">Refaire…</button>`:''}</div>${versions(j,'image:'+i,false)}</div>
<div class="asset">${s.clip?`<video src="${assetURL(j,s.clip)}" controls autoplay preload="metadata"></video>`:`<div class="asset-placeholder">${ico('film')}<small>clip à tourner</small></div>`}<div class="mini-actions"><button class="secondary" data-upload="clip:${i}" data-type="video">${s.clip?'Remplacer':'Importer'}</button>${s.clip?`<button class="secondary redo" data-redo="clip:${i}">Refaire…</button>`:''}</div>${versions(j,'clip:'+i,true)}</div></div>
<div class="scene-text"><div class="scene-text-head"><h2>${i+1}. ${esc(shortTitle(s)||'Scène')}</h2><small>${j.config.clip_seconds||8} s</small></div>${(s.dialogue||[]).map(l=>`<p><b>${esc((names[l.speaker]||l.speaker).toUpperCase())}</b> « ${esc(l.text)} »</p>`).join('')}${s.meaning?`<p class="hint">${esc(s.meaning)}</p>`:''}${sceneReport(j,i)}${sceneTools(j,i)}</div></div><button class="secondary" data-scene-close="1">Fermer</button>`}
document.addEventListener('click',e=>{const o=e.target.closest?.('[data-scene-open]');const c=e.target.closest?.('[data-scene-close],[data-upload],[data-redo]');let box=$('#sceneBox');
 if(c&&box?.open){setTimeout(()=>box.close(),0);if(c.dataset.sceneClose)return;}
 if(!o)return;const j=state.jobs.find(j=>j.id===selected);if(!j)return;if(!box){box=document.createElement('dialog');box.id='sceneBox';box.addEventListener('click',ev=>{if(ev.target===box)box.close()});document.body.append(box);}
 box.innerHTML=sceneModal(j,Number(o.dataset.sceneOpen));paintIcons();box.showModal();});
function alertsNotice(j){const st=j.stall?`<div class="notice human stall"><b>Bloqué : la vidéo ne progresse plus</b><p class="hint">${esc(j.stall.reason)}</p><p class="hint">${esc(j.stall.hint)}</p>${j.stall.retry?`<button class="primary" data-retry-step="${j.stall.paid?1:0}">Relancer cette étape</button>`:''}</div>`:'';return st+alertsNotice0(j)}
function alertsNotice0(j){const al=j.alerts||[],act=al.filter(a=>a.level==='action'),auto=al.filter(a=>a.level==='auto');const last=[...(j.events||[])].reverse()[0];
 const fallback=j.status==='attention'&&!act.length&&!['login','challenge'].includes(j.last_error?.kind)&&last?[{text:last.text,at:last.at}]:[];
 const box=(cls,title,list)=>list.length?`<div class="notice ${cls}"><b>${title}</b>${list.map(a=>`<p class="hint">${esc(a.text)}</p>`).join('')}</div>`:'';
 return (j.status==='attention'?box('human','⚠ Action requise',[...act.slice(-2),...fallback]):'')+box('uncertain','Décidé automatiquement — à vérifier avant de publier',auto.slice(-3))}
function detail(){const j=state.jobs.find(j=>j.id===selected);if(!j)return '';const task=state.tasks.find(t=>t.job===j.id&&['queued','claimed'].includes(t.status));
 const n=(j.scenes||[]).length||j.config.scene_count,secs=n*(j.config.clip_seconds||8);
 return `<section class="detail episode"><div class="episode-head"><button class="link-btn back" data-back-studio="1">Retour au Studio</button><div class="episode-title"><h1>${esc(j.title)}</h1><p>${secs} s · ${n} scènes · ${esc((j.config.language||'').split(' ')[0])} · ${j.config.format==='horizontal'?'16:9':'9:16'} · ${esc(statusLabels[j.status]||j.status)}${task?' · '+esc(nextAction(j)):''}</p>${variantLinks(j)}</div>
<div class="actions">${j.scenes?.some(s=>s.image)?`<a class="secondary" href="/api/job/${j.id}/images.zip" download>${ico('download')} Télécharger les images</a>`:''}${j.script?'<button class="secondary" data-show-text="1">Le texte</button>':''}${j.status!=='done'&&!['ideas','sheet'].includes(j.stage)?`<button class="primary" data-command="resume">${ico('refresh')} Boucle complète</button>`:''}${j.status!=='done'?(state.night?.ids||[]).includes(j.id)?'<button class="secondary" data-night="remove">Retirer de la file de nuit</button>':'<button class="secondary" data-night="add">File de nuit</button>':''}<button class="secondary" data-delete-job="1">Supprimer…</button></div></div>
${tracker(j)}${alertsNotice(j)}${dryRunNotice(j)}${humanNotice(j)}${accountNotice(j)}${uncertainClips(j)}${ideasPanel(j)}${sheetPanel(j)}${scriptReview(j)}${j.stage==='quality'?qualityReview(j):''}
${j.final?`<section class="panel final-block"><div class="final-row"><video class="final-video" src="${j.final}" controls></video><div><h2>Ton épisode est prêt</h2><div class="actions column"><a class="primary" href="${j.final}" download="fruchtdrama.mp4">${ico('download')} Télécharger le MP4</a><a class="secondary" href="${j.cover}?download=1" download>${ico('download')} Miniature</a><a class="secondary" href="/media/${j.id}/description.txt?download=1" download="description.txt">${ico('download')} Description</a><button class="secondary" data-action="copyDescription">Copier la description</button>${j.publication?`<a class="secondary" href="${j.publication}?download=1" download>${ico('download')} Kit de publication</a>`:''}<button class="secondary" data-series="1">Écrire la suite (partie ${(j.series?.part||1)+1})…</button></div><details><summary>Description TikTok</summary><textarea id="finalDescription" readonly rows="5">${esc(j.script?.description||'')}</textarea></details></div></div></section>`:''}
${originalityPanel(j)}${coverPanel(j)}${castSection(j)}
${(j.scenes||[]).length?`<h2 class="section-h">Scènes</h2><div class="scene-wall">${j.scenes.map((s,i)=>sceneTile(j,s,i)).join('')}</div>`:''}
<details class="more"><summary>Réglages, références et journal</summary><div class="form-grid">${(j.config.video_engine||'flow')!=='flow'?`<p class="hint engine-badge">Moteur vidéo : <b>${esc({grok:'Grok Imagine',arena:'LMArena vidéo'}[j.config.video_engine])}</b> · comptes dans Mes comptes</p>`:''}<label ${(j.config.video_engine||'flow')!=='flow'?'hidden':''}>Compte Flow de cet épisode<select id="jobProfile">${profileOptions(j.flow_profile)}</select></label><label>IA de scénario<select id="jobProvider"><option value="chatgpt" ${j.config.provider==='chatgpt'?'selected':''}>ChatGPT</option><option value="claude" ${j.config.provider==='claude'?'selected':''}>Claude</option></select></label></div>
${j.selected?.url?`<p class="hint">Référence : <a href="${esc(j.selected.url)}" target="_blank" rel="noreferrer">ouvrir TikTok ${ico('external')}</a>${j.selected.basis?' · '+esc(j.selected.basis):''}</p>`:''}${editorialReview(j)}${j.stage!=='quality'?qualityReview(j).replace('<details open>','<details>'):''}
${task?`<details><summary>Prompt de la tâche · copie manuelle possible</summary><pre>${esc(task.payload.prompt||task.payload.query)}</pre><button class="secondary" data-copy-task="${task.id}">Copier le prompt</button></details>`:''}
<details><summary>Importer un scénario JSON</summary><textarea id="scriptInput" rows="5" placeholder="Collez ici le JSON du scénario"></textarea><button class="secondary" data-action="script">Valider le scénario</button></details>
<div class="logs">${j.events.slice(-18).reverse().map(e=>`<p><time>${new Date(e.at).toLocaleTimeString('fr',{hour:'2-digit',minute:'2-digit'})}</time>${esc(e.text)}</p>`).join('')}</div></details></section>`}

// ============================================================================================
// Atelier-identical Studio (owner request 03/11/2026, from screenshots of the Atelier):
// Studio = stories (cards with next action and a direct button) → story page (parts, next part,
// characters) → part page (step cards, final video, thumbnail, publication, characters, scenes).
// These declarations replace the earlier studio() and detail().
// ============================================================================================
let selectedStory=null,showNight=false;
const rootOf=j=>{let x=j,guard=0;while(x?.variant?.of&&guard++<5){const o=state.jobs.find(y=>y.id===x.variant.of);if(!o)break;x=o;}return x;};
const storyKey=j=>{const r=rootOf(j);return r.series?.id||r.id;};
function stories(){const by=new Map();for(const j of state.jobs){const k=storyKey(j);if(!by.has(k))by.set(k,[]);by.get(k).push(j);}
 return [...by.entries()].map(([key,parts])=>{parts.sort((a,b)=>(a.series?.part||1)-(b.series?.part||1)||(a.variant?1:0)-(b.variant?1:0)||String(a.created).localeCompare(String(b.created)));
  const main=parts.filter(p=>!p.variant),open=main.filter(p=>p.status!=='done'),current=open[0]||main[main.length-1]||parts[0],first=parts.find(p=>!p.variant&&(p.series?.part||1)===1)||parts[0];
  return {key,parts,current,variantsOpen:parts.filter(p=>p.variant&&p.status!=='done'),title:(displayTitle(first)||'Histoire').replace(/\s+—\s+partie\s+\d+$/i,''),updated:parts.map(p=>p.updated||p.created).sort().pop()};}).sort((a,b)=>String(b.updated).localeCompare(String(a.updated)));}
const UPPER=t=>String(t||'').toUpperCase();
// Counted per story, like the cards: one story = one card = one status.
function storyGroups(){return stories().reduce((a,st)=>{const k=st.current.status==='done'?'ready':stageGroup(st.current);a[k]=(a[k]||0)+1;return a},{});}
function badgeOf(j){const g=stageGroup(j);return j.status==='done'?['Prête','ready']:{write:['À écrire','write'],draw:['À dessiner','draw'],shoot:['À tourner','shoot'],edit:['À finir','edit']}[g]||['À finir','edit'];}
// Next action + direct button, like "Tourner 3 clip(s) · Tourner".
function quickAction(j){const n=(j.scenes||[]).length,missing=k=>(j.scenes||[]).filter(s=>!s[k]).length;
 if(j.status==='done')return ['Prête à publier',null];
 if(j.stage==='ideas')return j.ideas?.length?['Choisir une des dix histoires','Choisir']:['Dix histoires en cours…',null];
 if(j.stage==='sheet')return j.sheet?['Valider la fiche','Valider']:['Fiche en cours…',null];
 if(['research','script'].includes(j.stage))return ['Écrire l’épisode',j.status==='running'?null:'Écrire'];
 if(j.stage==='characters')return ['Dessiner les personnages',j.status==='running'?null:'Dessiner'];
 if(j.stage==='images')return ['Dessiner '+missing('image')+' planche(s)',j.status==='running'?null:'Dessiner'];
 if(['clips','quality'].includes(j.stage))return ['Tourner '+missing('clip')+' clip(s)',j.status==='running'?null:'Tourner'];
 return ['Monter la vidéo finale',j.status==='running'||j.status==='rendering'?null:'Monter'];}
// Atelier "0 en 6 h": what was made in the last six hours, always shown.
function recent6h(){const since=Date.now()-6*3600000,done=k=>state.tasks.filter(t=>t.status==='done'&&k.includes(t.kind)&&t.done_at&&Date.parse(t.done_at)>=since).length;
 return {images:done(['chat_image']),clips:done(['flow_video','engine_video']),videos:state.jobs.filter(j=>j.rendered_at&&Date.parse(j.rendered_at)>=since).length};}
function quotaChips(){const now=Date.now()/1000,hh=t=>new Date(t*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});const r=recent6h();
 const chips=[`<span class="qchip" title="images ChatGPT faites ces 6 dernières heures">${ico('image')} ${r.images} en 6 h</span>`,`<span class="qchip" title="clips faits ces 6 dernières heures">${ico('film')} ${r.clips} en 6 h</span>`,`<span class="qchip" title="vidéos montées ces 6 dernières heures">${ico('create')} ${r.videos} en 6 h</span>`];
 for(const q of state.quota_status||[])if(q.blocked)chips.push(q.blocked?`<span class="qchip bad">${ico(q.service.includes('image')?'image':'book')} ${esc(q.label)} au mur, reprise ${hh(q.retry_at)}</span>`:`<span class="qchip">${ico(q.service.includes('image')?'image':'book')} ${q.used} en 6 h</span>`);
 for(const e of ['grok','arena']){const acc=(state.engine_accounts||[]).filter(a=>a.engine===e);if(acc.length&&acc.every(a=>a.wall&&a.wall.until>now))chips.push(`<span class="qchip bad">${ico('film')} ${e==='grok'?'Grok':'Arena'} au mur, reprise ${hh(Math.min(...acc.map(a=>a.wall.until)))}</span>`);}
 const flow=state.profiles.reduce((a,p)=>a+(p.balance||0),0);chips.push(`<span class="qchip">${ico('coins')} ${flow} crédits Flow</span>`);return chips.join('');}
function studio(){if(selected&&state.jobs.some(j=>j.id===selected))return detail();if(selectedStory&&stories().some(s=>s.key===selectedStory))return storyPage();
 const g=storyGroups();
 return `<div class="intro"><div><h1>Studio</h1><p>Tes histoires et leurs parties.</p></div><div class="actions"><button class="secondary" data-night-toggle="1">File de nuit</button><button class="primary" data-action="new">${ico('plus')} Nouvelle histoire</button></div></div>
${showNight||(state.night?.ids||[]).length?nightPanel():''}
<div class="studio-top"><div class="counters">${[['draw','à dessiner'],['shoot','à tourner'],['ready','prêtes'],['write','à écrire']].map(([k,l])=>`<div class="counter"><strong>${g[k]||0}</strong><small>${l}</small></div>`).join('')}</div><div class="quota-box">${quotaChips()}</div></div>
<div class="story-grid">${stories().map(st=>{const j=st.current,run=isActive(j),[label,tone]=run?['En cours','run']:badgeOf(j),[next,btn]=run?[liveLine(j),'']:quickAction(j),c=cover(j)||st.parts.map(cover).find(Boolean);
 return `<article class="story-card${run?' running':''}" data-story="${esc(st.key)}" ${run?`data-open-job="${j.id}"`:''} role="button" tabindex="0" aria-label="Ouvrir ${esc(UPPER(st.title))}">${c?`<img src="${c}" alt="">`:`<span class="studio-ph">${ico('film')}</span>`}<span class="sbadge ${tone}">${label}</span><div class="story-body"><b>${esc(UPPER(st.title))}</b><span class="seg">${segments(j).map(([l,v])=>`<i title="${l}" style="--v:${Math.round(v*100)}%"></i>`).join('')}</span><div class="story-next"><small>${esc(next)}${st.variantsOpen.length&&!run?` · ${st.variantsOpen.map(v=>v.config?.format==='horizontal'?'16:9':esc((v.config?.language||'').split(' ')[0]||'version')).join(', ')} à finir`:''}</small>${btn?(()=>{const f=quickLight(j,btn);return `<button class="secondary light ${f.tone}" data-quick="${j.id}" title="${esc(f.title)}" ${f.tone==='red'?'disabled':''}><i class="feu"></i>${btn}</button>`})():''}</div></div></article>`}).join('')||`<div class="empty"><h3>Ta première histoire commence ici</h3><button class="primary" data-action="new">${ico('plus')} Nouvelle histoire</button></div>`}</div>`}
// Personnages like the Atelier: title with the Simple | Détaillé switch and Refaire on the right, the shared sheet,
// then one compact pill per character (name, state dot, arrow) that unfolds to its description, its image when
// it has its own, and Remplacer/Importer. Unfolded pills survive the periodic refresh.
const openCast=new Set();
document.addEventListener('toggle',e=>{const k=e.target?.dataset?.cast;if(k)e.target.open?openCast.add(k):openCast.delete(k);},true);
const castDrawn=j=>!!(j.character_sheet_file||(j.characters||[]).some(c=>c.file));
function castPill(j,c,edit){const sheet=usesSheet(j),k=j.id+':'+c.id,own=!sheet&&c.file,ready=own||sheet&&j.character_sheet_file;
 return `<details class="cast-pill" data-cast="${esc(k)}" ${openCast.has(k)?'open':''}><summary><b>${esc(UPPER(c.name))}</b><i class="ndot${ready?' ok':''}" title="${ready?'dessiné':'pas encore dessiné'}"></i><span class="caret" aria-hidden="true"></span></summary><div class="cast-more">${own?`<img src="${assetURL(j,c.file)}" alt="${esc(c.name)}">`:''}<p>${esc(c.appearance||'Pas encore de description.')}</p>${edit&&!sheet?`<button class="secondary" data-upload="character:${c.id}" data-type="image">${c.file?'Remplacer':'Importer'}</button>`:''}</div></details>`;}
function castSection(j){if(!j.characters?.length)return '';const sheet=usesSheet(j),drawn=castDrawn(j),mode=j.config?.characters_detail==='detailed'?'detailed':'simple';
 const busy=state.tasks.some(t=>t.job===j.id&&['queued','claimed'].includes(t.status)&&String(t.slot||'').startsWith('character'));
 const locked=drawn||busy,levels=[['simple','Simple'],['detailed','Détaillé']];
 const toggle=locked?`<div class="seg-switch locked" title="${drawn?'Personnages déjà dessinés':'Personnages en cours de dessin'} : niveau ${mode==='detailed'?'Détaillé':'Simple'}">${levels.map(([v,l])=>`<span class="${mode===v?'on':''}">${l}</span>`).join('')}</div>`
  :`<div class="seg-switch" role="group" aria-label="Niveau des personnages">${levels.map(([v,l])=>`<button type="button" class="${mode===v?'on':''}" aria-pressed="${mode===v}" data-cast-detail="${v}">${l}</button>`).join('')}</div>`;
 const redo=drawn?`<button class="secondary" data-redo="${sheet?'characters':'character:'+j.characters[0].id}">Refaire</button>`:'';
 return `<div class="cast-head"><h2 class="section-h">Personnages</h2>${toggle}${redo}</div><div class="cast-row">${sheet?`<div class="cast-sheet">${asset(j,j.character_sheet_file,'Feuille commune : '+j.characters.map(c=>c.name).join(', '),'characters')}</div>`:''}${j.characters.map(c=>castPill(j,c,true)).join('')}</div>`;}
// Story page: the latest part's sheet and every character met in the parts (latest description wins).
function storyCast(st){const parts=st.parts.filter(p=>(p.characters||[]).length);if(!parts.length)return '';
 const seen=new Map();for(const p of parts)for(const c of p.characters)seen.set(c.name,[p,c]);
 const withSheet=[...parts].reverse().find(p=>usesSheet(p)&&p.character_sheet_file);
 return `<h2 class="section-h">Personnages</h2><div class="cast-row">${withSheet?`<div class="cast-sheet"><div class="asset"><img src="${assetURL(withSheet,withSheet.character_sheet_file)}" alt="Feuille commune"><b>Feuille commune</b></div></div>`:''}${[...seen.values()].map(([p,c])=>castPill(p,c,false)).join('')}</div>`;}
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-cast-detail]');if(!b||!selected)return;
 try{await api('/api/job/'+selected,{action:'characters_detail',level:b.dataset.castDetail});await refresh(true);toast(b.dataset.castDetail==='detailed'?'Personnages en Détaillé : trois quarts, gros plan, détails':'Personnages en Simple : feuille de face');}catch(err){toast(err.message)}});
function storyPage(){const st=stories().find(s=>s.key===selectedStory),last=st.parts.filter(p=>!p.variant).pop(),nextPart=(last.series?.part||1)+1;
 return `<button class="link-btn back" data-back-studio="1">← Studio</button><div class="intro"><div><h1>${esc(UPPER(st.title))}</h1></div><button class="secondary" data-delete-story="${esc(st.key)}">Supprimer l’histoire</button></div>
<h2 class="section-h">Les parties</h2><div class="story-grid parts">${st.parts.map(p=>{const c=cover(p);const tag=p.variant?(p.variant.kind==='horizontal'?'16:9':p.config.language.split(' ')[0]):'Partie '+(p.series?.part||1);
 return `<article class="story-card part" data-job="${p.id}" role="button" tabindex="0" aria-label="Ouvrir ${esc(UPPER(p.title))}">${c?`<img src="${c}" alt="">`:`<span class="studio-ph">${ico('film')}</span>`}<span class="sbadge part">${esc(tag)}</span><div class="story-body"><b>${esc(UPPER(p.title))}</b><span class="seg">${segments(p).map(([l,v])=>`<i title="${l}" style="--v:${Math.round(v*100)}%"></i>`).join('')}</span><small>${((p.scenes||[]).length||p.config.scene_count)*(p.config.clip_seconds||8)} s</small><button class="link-btn" data-delete-part="${p.id}">Supprimer</button></div></article>`}).join('')}
<button class="story-card add" ${last.status==='done'?`data-next-part="${last.id}"`:'disabled'}><span class="plus">${ico('plus')}</span><b>Créer la partie ${nextPart}</b><small>${last.status==='done'?'la suite, avec les mêmes personnages':'termine d’abord la partie '+(nextPart-1)}</small></button></div>
${storyCast(st)}`}
// Publication like the Atelier: « hook », « Titre · Partie N », the chosen end call, then hashtags of the niche
// (generic AI hashtags such as #IA drown the video among every AI video, the Atelier advises against them).
const PART_WORD={'Français (fr-FR)':'Partie','English (en-US)':'Part','Español (es-ES)':'Parte','Português (pt-BR)':'Parte','Deutsch (de-DE)':'Teil'};
const FRUIT_TAGS={'Français (fr-FR)':['#histoiredefruit','#fruitstory','#fruitdrama'],'English (en-US)':['#fruitstory','#fruitdrama','#storytime'],'Español (es-ES)':['#frutinovelas','#historiasdefrutas','#fruitstory'],'Português (pt-BR)':['#historiadefrutas','#novelasdefrutas','#fruitstory'],'Deutsch (de-DE)':['#fruchtgeschichte','#fruitstory','#fruitdrama']};
const GENERIC_TAGS=new Set(['#ia','#ai','#ki','#creationia','#aiart','#aigenerated','#intelligenceartificielle','#artificialintelligence']);
function pubText(j){const s=j.script||{},lang=j.config.language,part=j.series?.part||1,desc=String(s.description||'');
 const own=(desc.match(/#[\p{L}\p{N}_]+/gu)||[]).filter(h=>!GENERIC_TAGS.has(h.toLowerCase()));
 const tags=[...new Set([...((j.config.niche||'Fruits')==='Fruits'?FRUIT_TAGS[lang]||[]:[]),...own])].slice(0,8);
 const body=desc.replace(/#[\p{L}\p{N}_]+/gu,'').replace(/[ \t]+\n/g,'\n').trim(),hook=s.hook_text||(j.scenes?.[0]?.dialogue?.[0]?.text)||'';
 const title=`${s.title||j.title} · ${PART_WORD[lang]||'Partie'} ${part}`,lastLine=(j.scenes?.[j.scenes.length-1]?.dialogue||[]).slice(-1)[0]?.text||'',call=j.sheet?.end_call||(/\b1\b.*\b2\b|abonne|partie\s*2|suite/i.test(lastLine)?lastLine:'');
 return {title,text:[hook?`« ${hook.replace(/^«\s*|\s*»$/g,'')} »`:'','',`${s.title||j.title} · ${PART_WORD[lang]||'Partie'} ${part}`,call,'',body,'',tags.join(' ')].join('\n').replace(/\n{3,}/g,'\n\n').trim()};}
function publication(j){if(!j.final)return '';return `<section class="panel pub-card"><div class="section-title"><h3>Publication</h3><div class="actions"><button class="secondary" data-copy-pub="1">Tout copier</button><button class="secondary icon" data-command="distance" title="Réécrire titre, accroche et description">${ico('refresh')}</button></div></div><p class="pub-title">${esc(pubText(j).title)}</p><p class="hint pub-desc">${esc(pubText(j).text)}</p></section>`}
function thumbCard(j){const boards=(j.scenes||[]).map((s,i)=>[s,i]).filter(([s])=>s.image);if(!boards.length)return '';const base=Number.isInteger(j.cover_base)?j.cover_base:boards[0][1];
 return `<section class="panel media-card"><div class="media-prev">${j.cover?`<img src="${j.cover}" alt="Miniature">`:'<span>Miniature</span>'}</div><div><h3>Miniature</h3><div class="cover-picks">${boards.slice(0,8).map(([s,i])=>`<button class="${i===base?'on':''}" data-cover-base="${i}" title="Scène ${i+1}"><img src="${assetURL(j,s.image)}" alt=""></button>`).join('')}</div><div class="actions column-left">${j.cover?`<a class="secondary" href="${j.cover}?download=1" download>Télécharger</a>`:''}<button class="secondary" data-originality="1">${ico('eye')} Contrôler</button>${j.cover_file?'<button class="secondary" data-redo="cover">Refaire…</button>':'<button class="secondary" data-cover-make="1">Faire la miniature</button>'}</div></div></section>`}
function finalCard(j){if(!j.final)return '';return `<section class="panel media-card"><div class="media-prev video"><video src="${j.final}" controls preload="metadata"></video></div><div><h3>Vidéo finale</h3><p class="hint">${esc((j.qc?.export||'').replace(/^Réussi : MP4 /,'').replace(/, audio normalisé\.?$/,''))} · ${j.config.karaoke===false?'sous-titres simples':'sous-titres karaoké'}${(j.script?.hook_text||j.script?.cover_title)?' · accroche à l’écran':''}${j.originality?' · originalité '+j.originality.score+' %':''}</p><div class="actions"><a class="secondary" href="${j.final}" download="${esc(j.title)}.mp4">${ico('download')} Télécharger</a><button class="secondary" data-series="1">Écrire la suite…</button></div></div></section>`}
function originalityModal(j){const o=j.originality;return o?originalityPanel(j)+'<button class="secondary" data-scene-close="1">Fermer</button>':`<p>Pas encore contrôlée.</p><button class="primary" data-command="originality">Contrôler l’originalité</button> <button class="secondary" data-scene-close="1">Fermer</button>`}
function trackAction(j,i,v){const idle=!['running','rendering'].includes(j.status);const flagged=(j.quality_report?.clips||[]).filter(c=>(c.speech?.match??1)<.85).length;
 const a={1:(j.character_sheet_file||j.characters?.some(c=>c.file))?`<button class="link-btn" data-redo="${usesSheet(j)?'characters':'character:'+j.characters[0].id}">Refaire…</button>`:'',
  2:v>=1?`<button class="link-btn" data-scene-open="0">Refaire…</button>`:idle&&j.stage==='images'?'<button class="link-btn" data-command="resume">Générer</button>':'',
  3:v>=1&&flagged&&['cover','edit','done'].includes(j.stage)?`<button class="link-btn" data-scene-open="${(j.quality_report.clips||[]).findIndex(c=>(c.speech?.match??1)<.85)}" title="Paroles sous 85 % acceptées ; écoute avant de publier">${flagged} acceptés avec réserve</button>`:v>=1&&flagged?`<span class="flag">${flagged} à revoir</span>`:v>=1?`<button class="link-btn" data-scene-open="0">Refaire…</button>`:idle&&j.stage==='clips'?'<button class="link-btn" data-command="resume">Générer</button>':'',
  4:j.final?'<button class="link-btn" data-command="rerender">Remonter…</button>':idle&&['edit','cover'].includes(j.stage)?'<button class="link-btn" data-command="resume">Monter…</button>':''}[i];return a?`<span class="track-act">${a}</span>`:''}
// « Au fil de l'histoire » (like the Atelier): the cast sheet redrawn after a visible change, used from that scene on.
function storyStates(j){const changes=j.script?.state_changes||[];if(!changes.length)return '';
 const name=id=>UPPER((j.characters.find(c=>c.id===id)||{}).name||id),used=c=>(j.scenes||[]).some((s,i)=>i>=c.from_scene-1&&s.image&&(s.characters||[]).includes(c.character));
 return `<div class="story-states"><h3>Au fil de l’histoire</h3>${changes.map((c,k)=>{const s=(j.state_sheets||[]).find(x=>x.character===c.character&&x.from_scene===c.from_scene);
  const note=s?.file?'':s?.skipped?'refusée par ChatGPT : les planches gardent la feuille des personnages':j.config.quality==='economy'?'pas de feuille d’état en Économie':'dessinée avant les planches';
  return `<div class="state-row">${s?.file?`<img src="${assetURL(j,s.file)}" alt="Feuille d’état dès la scène ${c.from_scene}">`:`<div class="asset-placeholder">${ico('image')}</div>`}<div><b>Dès la scène ${c.from_scene}</b><p>${esc(name(c.character))} : ${esc(c.change)}</p>${note?`<small>${note}</small>`:''}${s?.file&&!used(c)?`<button class="link-btn" data-redo="state:${k}">Refaire…</button>`:''}</div></div>`}).join('')}</div>`}
function detail(){const j=state.jobs.find(j=>j.id===selected);if(!j)return '';const st=stories().find(s=>s.parts.some(p=>p.id===j.id));const n=(j.scenes||[]).length||j.config.scene_count,secs=n*(j.config.clip_seconds||8);
 return `<section class="detail episode"><button class="link-btn back" data-back-story="${esc(st?.key||'')}">← ${esc(UPPER(st?.title||'Studio'))}</button>
<div class="episode-title"><h1>${esc(UPPER(j.title))} <button class="link-btn edit" data-rename="1" title="Renommer">✎</button></h1><p>${secs} s · ${n} scènes</p>${variantLinks(j)}</div>
<div class="episode-actions">${j.scenes?.some(s=>s.image)?`<a class="secondary" href="/api/job/${j.id}/images.zip" download>Télécharger les images</a>`:''}${j.status!=='done'?(state.night?.ids||[]).includes(j.id)?'<button class="secondary" data-night="remove">Retirer de la file de nuit</button>':'<button class="secondary" data-night="add">File de nuit</button>':''}${j.script?'<button class="secondary" data-show-text="1">Le texte</button>':''}${!['ideas','sheet'].includes(j.stage)?`<button class="primary" data-command="resume">▶ Boucle complète</button>`:''}</div>
${alertsNotice(j)}${dryRunNotice(j)}${staleNotice(j)}${j.montage_stale&&j.final?`<div class="notice dry"><b>Un clip a changé depuis le montage</b><p class="hint">La vidéo finale ne le contient pas encore. Le remontage est gratuit (aucun crédit).</p><button class="primary" data-command="rerender">Remonter la vidéo</button></div>`:''}${humanNotice(j)}${accountNotice(j)}${uncertainClips(j)}${ideasPanel(j)}${sheetPanel(j)}${scriptReview(j)}${j.stage==='quality'?qualityReview(j):''}
${tracker(j)}${finalCard(j)}${thumbCard(j)}${publication(j)}
${castSection(j)}${j.characters.length?storyStates(j):''}
${(j.scenes||[]).length?`<h2 class="section-h">Scènes</h2><div class="scene-wall">${j.scenes.map((s,i)=>sceneTile(j,s,i)).join('')}</div>`:''}
<details class="more"><summary>Journal et réglages</summary><div class="form-grid"><label ${(j.config.video_engine||'flow')!=='flow'?'hidden':''}>Compte Flow de cet épisode<select id="jobProfile">${profileOptions(j.flow_profile)}</select></label><label>IA de scénario<select id="jobProvider"><option value="chatgpt" ${j.config.provider==='chatgpt'?'selected':''}>ChatGPT</option><option value="claude" ${j.config.provider==='claude'?'selected':''}>Claude</option></select></label></div><button class="link-btn" data-delete-job="1">Supprimer cet épisode…</button><div class="logs">${j.events.slice(-18).reverse().map(e=>`<p><time>${new Date(e.at).toLocaleTimeString('fr',{hour:'2-digit',minute:'2-digit'})}</time>${esc(e.text)}</p>`).join('')}</div></details></section>`}
document.addEventListener('click',async e=>{const el=e.target.closest?.('.story-card.part[data-job],[data-story],[data-back-story],[data-night-toggle],[data-quick],[data-delete-story],[data-delete-part],[data-next-part],[data-rename],[data-originality],[data-copy-pub]');if(!el)return;
 if(el.matches('[data-story]')&&e.target.closest('[data-quick]'))return;
 // Owner report 04/11/2026: a part card (not a button) did nothing, so a video being made could not be reopened.
 if(el.matches('.story-card.part')){if(e.target.closest('button'))return;e.stopImmediatePropagation();selected=el.dataset.job;page='studio';location.hash='job='+selected;render();window.scrollTo(0,0);return}
 e.stopImmediatePropagation();try{
 // A story being made opens straight on the part in progress (its progress, not the list of parts).
 if(el.dataset.story&&el.dataset.openJob){selectedStory=el.dataset.story;selected=el.dataset.openJob;location.hash='job='+selected;render();window.scrollTo(0,0);return}
 if(el.dataset.story){selectedStory=el.dataset.story;selected=null;render();window.scrollTo(0,0);return}
 if('backStory' in el.dataset){selected=null;selectedStory=el.dataset.backStory||null;history.replaceState(null,'',location.pathname);render();window.scrollTo(0,0);return}
 if(el.dataset.nightToggle){showNight=!showNight;render();return}
 if(el.dataset.quick){const j=state.jobs.find(x=>x.id===el.dataset.quick);if(['ideas','sheet'].includes(j.stage)){selected=j.id;render();return}if(!confirmCost(j,quickAction(j)[1]||'Continuer'))return;await api('/api/job/'+j.id,{action:'resume',flow_profile:j.flow_profile});await refresh(true);toast('C’est parti : '+quickAction(j)[0].toLowerCase());return}
 if(el.dataset.deleteStory){const st=stories().find(s=>s.key===el.dataset.deleteStory);if(!window.confirm('Supprimer l’histoire « '+st.title+' » et ses '+st.parts.length+' partie(s) ? Les dossiers vont dans la corbeille.'))return;for(const p of st.parts)await api('/api/job/'+p.id,{action:'delete'});selectedStory=null;await refresh(true);toast('Histoire déplacée dans la corbeille');return}
 if(el.dataset.deletePart){e.preventDefault();if(!window.confirm('Supprimer cette partie ? Son dossier va dans la corbeille.'))return;await api('/api/job/'+el.dataset.deletePart,{action:'delete'});await refresh(true);return}
 if(el.dataset.nextPart){const note=window.prompt('Une idée pour la suite ? (facultatif)','');if(note===null)return;const r=await api('/api/job/'+el.dataset.nextPart,{action:'continue_series',note});selected=r.created;await refresh(true);toast('Partie suivante créée : mêmes personnages');return}
 const j=state.jobs.find(x=>x.id===selected);if(!j)return;
 if(el.dataset.rename){const t=window.prompt('Nouveau titre :',j.title);if(!t)return;await api('/api/job/'+j.id,{action:'rename',title:t});await refresh(true);return}
 if(el.dataset.originality){let box=$('#sceneBox');if(!box){box=document.createElement('dialog');box.id='sceneBox';box.addEventListener('click',ev=>{if(ev.target===box)box.close()});document.body.append(box);}box.innerHTML=originalityModal(j);paintIcons();box.showModal();return}
 if(el.dataset.copyPub){const p=pubText(j),text=p.title+'\n\n'+p.text;try{await navigator.clipboard.writeText(text);toast('Titre et description copiés')}catch{toast('Copie impossible : sélectionne le texte')}return}
 }catch(err){toast(err.message)}},true);
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-back-studio]');if(b){selected=null;selectedStory=null;render();window.scrollTo(0,0);}},true);

// --- Mes comptes: montage settings and story backups, like the Atelier --------------------------
function montagePanel(){const m=state.montage||{};const toggle=(k,l,h)=>`<label class="check"><input type="checkbox" data-montage-toggle="${k}" ${m[k]?'checked':''}> ${l}<span class="hint">${h}</span></label>`;
 return `<section class="panel montage-panel"><div><h3>Montage de mes vidéos</h3><p class="hint">Transitions, rythme et sous-titres de chaque nouvelle vidéo, production automatique comprise. Une vidéo déjà montée garde les siens.</p><p class="hint"><b>${esc(state.montage_summary||'')}</b></p></div>
<div><h4>Transitions</h4><div class="lang-choice">${[['cut','Coupe franche'],['fade_short','Fondu léger'],['fade_long','Fondu long']].map(([v,l])=>`<button class="${m.transition===v?'primary':'secondary'}" data-montage-transition="${v}">${l}</button>`).join('')}</div>
<h4>Rythme</h4>${toggle('fast_cuts','Coupes rapides','deux ou trois cadrages dans un même plan, sans couper la parole')}${toggle('cut_silences','Couper les silences','les blancs avant la première et après la dernière réplique de chaque clip sont raccourcis')}
<h4>Sous-titres</h4>${toggle('karaoke','Karaoké','le mot change de couleur quand il est dit ; décoché : sous-titres simples')}</div></section>`}
function backupPanel(){const b=state.backups||{};return `<section class="panel backup-panel"><div><h3>Mes sauvegardes</h3><p class="hint">Chaque histoire est sauvegardée toute seule après chaque fabrication (texte, personnages, planches, miniature) dans <code>${esc(b.folder||'')}</code>. Si tu réinstalles le studio ou changes d’ordinateur, « Remettre des histoires » les fait revenir, en pause : rien n’est payé avant « Reprendre ».</p><p class="hint">${b.count?b.count+' histoire(s) sauvegardée(s).':'Aucune histoire sauvegardée pour l’instant.'}</p></div>
<div class="lang-choice"><button class="secondary" data-backup="save">Sauvegarder maintenant</button><button class="secondary" data-backup="restore">Remettre des histoires</button></div></section>`}
document.addEventListener('click',async e=>{const t=e.target.closest?.('[data-montage-transition],[data-backup]');if(!t)return;e.preventDefault();
 try{if(t.dataset.montageTransition){await api('/api/montage',{montage:{transition:t.dataset.montageTransition}});await refresh(true);toast('Montage enregistré');return}
  const r=await api('/api/backups',{action:t.dataset.backup});await refresh(true);toast(t.dataset.backup==='save'?'Histoires sauvegardées':r.restored?r.restored+' histoire(s) remise(s), en pause':'Aucune histoire à remettre');}catch(err){toast(err.message)}});
document.addEventListener('change',async e=>{const k=e.target.dataset?.montageToggle;if(!k)return;try{await api('/api/montage',{montage:{[k]:e.target.checked}});await refresh(true);toast('Montage enregistré');}catch(err){toast(err.message)}});

// --- Mes comptes, lot 4: guided account change, file access card, checks with three levels -----
let switchSite=null;
function filesCard(){const ok=state.ffmpeg;return `<article class="site-card files-card"><div class="site-head"><b>Accès à tes fichiers</b><span class="tag">NÉCESSAIRE</span></div><p>relire les clips téléchargés et monter la vidéo finale sur cet ordinateur</p><div class="site-foot">${ok?'<span class="dot-state ok">autorisé</span>':'<span class="dot-state bad">montage impossible : installe ffmpeg, puis relance le studio</span>'}</div></article>`}
function switchHelp(){if(!switchSite)return '';const name=(SITE_CARDS.find(c=>c[0]===switchSite)||[,switchSite])[1];
 return `<section class="panel switch-help" role="dialog" aria-label="Changer de compte ${esc(name)}"><h3>Changer de compte ${esc(name)}</h3><ol><li>Dans l’onglet ${esc(name)} de la fenêtre FruchtDrama, clique sur ton profil, puis « Se déconnecter ».</li><li>Connecte l’autre compte, toi-même : le studio ne voit jamais ton mot de passe.</li><li>Reviens ici et clique « C’est fait » : le studio revérifie les comptes.</li></ol><p class="hint">Tes histoires ne bougent pas : le studio continue avec le nouveau compte.</p>
<div class="lang-choice"><button class="secondary" data-site-open="${esc(switchSite)}">Ouvrir ${esc(name)}</button><button class="primary" data-switch-done="1">C’est fait</button><button class="secondary" data-switch-close="1">Fermer</button></div></section>`}
function controlsPanel(){const st=state.settings,row=(title,hint,attr,cur,opts)=>`<div class="control-row"><h4>${title}</h4><div class="lang-choice">${opts.map(([v,l,h])=>`<button class="${cur===v?'primary':'secondary'}" ${attr}="${v}" title="${h}">${l}</button>`).join('')}</div><p class="hint">${hint}</p></div>`;
 return `<section class="panel controls-panel"><div><h3>Contrôles et essai à blanc</h3><p class="hint">Choix appliqués aux nouveaux épisodes. En qualité Économie, les contrôles signalent seulement et personne ne regarde les clips.</p></div>
${row('Planches de la boucle complète','Avant les clips, ChatGPT compare les planches à la feuille des personnages (une pièce jointe pour cinq planches) ; celles qui ratent sont redessinées une fois, quatre au plus.','data-board-controls',st.board_controls||'none',[['redo','Refaire toutes seules','une image par planche ratée'],['report','Signaler seulement','noté dans le journal, la production continue'],['none','Pas de contrôle','aucune image ChatGPT en plus']])}
${row('Clips de la boucle complète','Paroles comparées au texte (85 % minimum) et revue visuelle ; un clip en défaut est refait une fois, un clip incertain t’est montré.','data-controls',st.controls||'report',[['redo','Refaire tout seul','un clip en défaut est refait une fois (crédits)'],['report','Signaler seulement','tu décides'],['none','Pas de contrôle','le plus rapide']])}
${row('Miniature de la boucle complète','ChatGPT regarde la miniature (une pièce jointe) et la redessine une fois s’il voit un défaut : titre coupé ou mal écrit, visage déformé, personnage qui ne ressemble pas ; en qualité Économie, il signale seulement.','data-cover-controls',st.cover_controls||'fix',[['fix','Corriger toute seule','une image de plus si un défaut est vu'],['report','Signaler seulement','noté dans le bandeau, le montage continue'],['none','Pas de contrôle','aucun message ChatGPT en plus']])}
${row('Regard sur les clips','ChatGPT regarde chaque clip à côté de sa planche : personnage en trop, apparence qui change, bouche qui parle à la place d’une autre.','data-clip-look',st.clip_look||'look',[['look','Les regarder aussi','une pièce jointe pour trois clips'],['ear','À l’oreille seulement','paroles seulement, pas de message ChatGPT']])}</section>`}
document.addEventListener('click',async e=>{const t=e.target.closest?.('[data-switch-help],[data-switch-done],[data-switch-close],[data-board-controls],[data-clip-look],[data-cover-controls]');if(!t)return;e.preventDefault();
 try{if(t.dataset.switchHelp){switchSite=t.dataset.switchHelp;render();return}
  if(t.dataset.switchClose){switchSite=null;render();return}
  if(t.dataset.switchDone){switchSite=null;await api('/api/sites',{action:'check'});await refresh(true);toast('Vérification des comptes demandée');return}
  await api('/api/settings',t.dataset.boardControls?{board_controls:t.dataset.boardControls}:t.dataset.coverControls?{cover_controls:t.dataset.coverControls}:{clip_look:t.dataset.clipLook});await refresh(true);toast('Contrôles enregistrés');}catch(err){toast(err.message)}});

// --- Le Filon, lot 5: niches and hashtags --------------------------------------------------------
document.addEventListener('click',async e=>{const t=e.target.closest?.('[data-filon-niche],[data-niche-editor],[data-niche-toggle],[data-filon-tag]');if(!t)return;e.preventDefault();
 try{if(t.dataset.nicheEditor){nicheEditor=!nicheEditor;render();return}
  if(t.dataset.filonTag){filonSearch=t.dataset.filonTag;render();return}
  if(t.dataset.filonNiche){await api('/api/filon',{niche:t.dataset.filonNiche});await refresh(true);return}
  const n=t.dataset.nicheToggle,mine=myNiches();await api('/api/filon',{niches:mine.includes(n)?mine.filter(x=>x!==n):[...mine,n]});await refresh(true);}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{if(e.target.id!=='nicheAdd')return;e.preventDefault();const n=String(new FormData(e.target).get('niche')||'').trim();if(!n)return;
 try{await api('/api/filon',{niches:[...myNiches(),n]});await refresh(true);toast('Niche ajoutée');}catch(err){toast(err.message)}});

// Access key buttons: activate (first time or new key) and check again (after a trip offline or a renewal).
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-licence]');if(!b)return;e.stopPropagation();
 try{b.disabled=true;const body=b.dataset.licence==='activate'?{key:($('#licenceKey')?.value||'').trim()}:{action:'check'};
  if(body.key==='')throw Error('Colle ta clé dans le champ, puis clique Activer.');
  const r=await api('/api/licence',body);state.licence=r.licence;render();
  toast(r.licence.mode==='active'?'Clé activée : bonne création !':r.licence.message||'Vérification faite');}
 catch(err){toast(err.message)}finally{b.disabled=false}},true);
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.id==='licenceKey')document.querySelector('[data-licence="activate"]')?.click()});

// Cards are articles: Enter or Space opens them like a click.
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('.story-card[role=button]')){e.preventDefault();e.target.click();}});

document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-restore]');if(!b)return;e.stopImmediatePropagation();
 const clip=b.dataset.restore.startsWith('clip:');if(!window.confirm(`Remettre cette version ${clip?'du clip':'de la planche'} ? Celle d’aujourd’hui est gardée : tu pourras la remettre aussi. Gratuit.`))return;
 try{await api('/api/job/'+selected,{action:'restore_version',slot:b.dataset.restore,file:b.dataset.file});$('#sceneBox')?.close();await refresh(true);toast('Version remise ; l’autre est gardée.');}catch(err){toast(err.message)}},true);

// « La planche a changé après le clip » (like the Atelier): those clips animate an old board.
function staleScenes(j){return (j.scenes||[]).map((s,i)=>s.clip&&s.clip_from&&s.image&&s.clip_from!==s.image?i:-1).filter(i=>i>=0);}
function staleNotice(j){const list=staleScenes(j);if(!list.length)return '';
 return `<div class="notice dry"><b>⚠ La planche a changé après le clip : scène${list.length>1?'s':''} ${list.map(i=>i+1).join(', ')}</b><p class="hint">Ces clips animent encore l’ancienne planche. Les refaire coûte ${esc(clipCost(j,list.length))}.</p><button class="primary" data-redo-clips="${list.join(',')}">Refaire ces clips…</button></div>`;}
// The scene window, like the Atelier: why a clip is flagged, what was heard, copy the prompts, edit the words.
function sceneReport(j,i){const c=(j.quality_report?.clips||[])[i]||{},sp=c.speech,v=((j.quality_report?.visual?.scenes)||[]).find(x=>x.index===i),out=[];
 if(c.hard_errors?.length)out.push(`<p class="flagline bad">⚠ ${esc(c.hard_errors.join(' · '))}</p>`);
 if(v&&v.status&&v.status!=='ok')out.push(`<p class="flagline warn">⚠ Regard sur le clip : ${esc(String(v.detail||'').slice(0,320))}</p>`);
 if(sp?.text)out.push(`<p class="heard ${sp.match<.85?'warn':''}">Entendu : « ${esc(sp.text)} »${sp.match!=null?` <small>${Math.round(sp.match*100)} % du texte</small>`:''}</p>`);
 if(j.scenes[i].text_after_clip)out.push('<p class="flagline warn">Texte modifié après le clip : refais le clip pour l’entendre.</p>');
 return out.join('');}
function sceneTools(j,i){const s=j.scenes[i];return `<div class="scene-tools"><button class="secondary" data-copy-prompt="video" data-i="${i}">📋 Copier le prompt du clip</button><button class="secondary" data-copy-prompt="image" data-i="${i}">📋 Copier le prompt de la planche</button>${(s.dialogue||[]).length?`<button class="secondary" data-edit-scene="${i}">✎ Modifier le texte</button>`:''}</div>
<div class="scene-edit" id="sceneEdit${i}" hidden>${(s.dialogue||[]).map((l,k)=>`<label>${esc(UPPER(Object.fromEntries(j.characters.map(c=>[c.id,c.name]))[l.speaker]||l.speaker))}<textarea rows="2" data-line="${k}">${esc(l.text)}</textarea></label>`).join('')}<div class="actions"><button class="primary" data-save-scene="${i}">Enregistrer</button><button class="secondary" data-cancel-scene="${i}">Annuler</button></div></div>`;}
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-redo-clips],[data-copy-prompt],[data-edit-scene],[data-save-scene],[data-cancel-scene],[data-add-google]');if(!b)return;e.stopImmediatePropagation();
 const j=state.jobs.find(x=>x.id===selected);
 try{
  if(b.dataset.addGoogle){await api('/api/sites',{action:'add_google'});toast('Page Google ouverte dans la fenêtre FruchtDrama : connecte le compte, le studio le détecte tout seul.');return}
  if(!j)return;
  if(b.dataset.redoClips){const list=b.dataset.redoClips.split(',').map(Number);if(!window.confirm(`Refaire ${list.length} clip(s) d’après leur nouvelle planche ?\n\nCoût : ${clipCost(j,list.length)}. Les clips actuels sont gardés (« Remettre »).`))return;await api('/api/job/'+j.id,{action:'redo_clips',scenes:list});await refresh(true);toast('Clips programmés');return}
  if(b.dataset.copyPrompt){const s=j.scenes[Number(b.dataset.i)];await navigator.clipboard.writeText(b.dataset.copyPrompt==='video'?(s.video_prompt||''):(s.image_prompt||''));toast('Prompt copié');return}
  if(b.dataset.editScene){const box=$('#sceneEdit'+b.dataset.editScene);box.hidden=false;box.querySelector('textarea')?.focus();return}
  if(b.dataset.cancelScene){$('#sceneEdit'+b.dataset.cancelScene).hidden=true;return}
  if(b.dataset.saveScene){const i=Number(b.dataset.saveScene),texts=[...$('#sceneEdit'+i).querySelectorAll('textarea')].map(x=>x.value);await api('/api/job/'+j.id,{action:'edit_scene',index:i,texts});$('#sceneBox')?.close();await refresh(true);toast(j.scenes[i].clip?'Texte enregistré : refais le clip pour l’entendre.':'Texte enregistré');return}
 }catch(err){toast(err.message)}},true);

// Quota light on the card button (like the Atelier): how much can be made right now, before clicking.
function quickLight(j,verb=''){const hh=t=>new Date(t*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}),sc=j.scenes||[];
 // The light follows the button's own verb: « Tourner » checks clips, « Dessiner » checks images.
 const shoot=/tourn/i.test(verb),draw=/dessin/i.test(verb);
 const images=shoot?0:(sc.length?sc.filter(s=>!s.image).length:0)||(draw?1:0),clips=draw?0:sc.length?sc.filter(s=>!s.clip).length:0;
 if(images){const q=(state.quota_status||[]).find(x=>x.service==='chatgpt_image');
  if(q?.blocked)return {tone:'red',title:`Images ChatGPT au mur : reprise vers ${hh(q.retry_at)} (estimation).`};
  if(q?.capacity!=null&&q.remaining!=null&&q.remaining<images)return {tone:'orange',title:`≈ ${q.remaining} planche(s) possible(s) maintenant sur ${images} ; le reste quand la limite revient (estimation).`};
  return {tone:'green',title:`${images} planche(s) à dessiner : possible maintenant.`};}
 if(clips){const e=j.config.video_engine||'flow';
  if(e==='flow'){const cost=Number(j.config.flow_cost||12),can=(state.profiles||[]).filter(p=>p.slot!=null&&p.auto_enabled!==false).reduce((a,p)=>a+Math.floor((p.balance||0)/cost),0);
   if(j.config.dry_run)return {tone:'green',title:'Essai à blanc : rien n’est envoyé.'};
   if(!can)return {tone:'red',title:'Plus de crédits Flow sur tes comptes : ajoute un compte Google ou attends la recharge.'};
   if(can<clips)return {tone:'orange',title:`${can} clip(s) possible(s) maintenant sur ${clips} avec tes crédits Flow ; le reste après la recharge.`};
   return {tone:'green',title:`${clips} clip(s) à tourner : ${can} possible(s) avec tes crédits Flow.`};}
  const acc=(state.engine_accounts||[]).filter(a=>a.engine===e),now=Date.now()/1000;
  if(acc.length&&acc.every(a=>a.wall&&a.wall.until>now))return {tone:'red',title:`Tous tes comptes ${e==='grok'?'Grok':'Arena'} sont au mur : reprise vers ${hh(Math.min(...acc.map(a=>a.wall.until)))}.`};
  return {tone:'green',title:`${clips} clip(s) à tourner.`};}
 return {tone:'green',title:'Possible maintenant.'};}

document.addEventListener('click',e=>{const t=e.target.closest?.('[data-open-episode]');if(!t)return;e.preventDefault();page='studio';selected=t.dataset.openEpisode;location.hash='job='+selected;render();window.scrollTo(0,0);});

document.addEventListener('click',async e=>{const t=e.target.closest?.('[data-retry-step]');if(!t)return;e.preventDefault();const paid=t.dataset.retryStep==='1';
 if(paid&&!window.confirm('As-tu vérifié dans Google Flow qu’aucun clip n’a été créé pour cette scène ? Relancer peut coûter des crédits.'))return;
 try{await api('/api/job/'+selected,{action:'retry_step',confirm_paid:paid});await refresh(true);toast('Étape relancée');}catch(err){toast(err.message||String(err));}});
